create table if not exists public.platform_verifications (id uuid primary key default gen_random_uuid(), started_at timestamptz not null default now(), finished_at timestamptz, status text not null check (status in ('RUNNING','PASSED','FAILED')), source_revision text, checks jsonb not null default '[]'::jsonb); alter table public.platform_verifications enable row level security; revoke all on public.platform_verifications from public,anon,authenticated; grant all on public.platform_verifications to service_role;
create or replace function public.enforce_application_space_integrity() returns trigger language plpgsql security invoker set search_path=public as $$ begin if new.status in ('CANCELLED','DECLINED') and old.assigned_space_id is not null then update public.fair_spaces set is_available=true where id=old.assigned_space_id; new.assigned_space_id=null; new.space_assigned_by_user_id=null; new.space_assigned_at=null; end if; if new.status='CONFIRMED' and new.assigned_space_id is null then raise exception 'SPACE_REQUIRED'; end if; return new; end $$;
revoke all on function public.enforce_application_space_integrity() from public,anon,authenticated;
create trigger application_space_integrity before update on public.applications for each row execute function public.enforce_application_space_integrity();
notify pgrst, 'reload schema';